{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/feature-split.json
    Features beside a picture. Axes: layout (grid: four plain features in two columns, cards: four features as cards and the actions, stats: two figure cards over three checked rows beside a square picture, metrics: four metric cards and the actions), mediaSide, tone.
    Props (p): id, title, lead, badge, level, features, stats, actions, layout, mediaSide, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_badge = ($p['badge'] ?? '')}
{var $v_level = ($p['level'] ?? 2)}
{var $v_features = ($p['features'] ?? null)}
{var $v_stats = ($p['stats'] ?? null)}
{var $v_actions = ($p['actions'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'grid')}
{var $v_mediaSide = ($p['mediaSide'] ?? 'end')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $f_1}
  {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => $v_title, 'ratio' => (ui_t(ui_eq($v_layout, 'stats')) ? '1/1' : '4/3')]])|noescape}
{/capture}
{capture $c_2}
  {if ui_t(ui_eq($v_layout, 'grid'))}
    {=ui_include('blocks/feature-pairs.latte', ['p' => ['features' => $v_features]])|noescape}
  {/if}
  {if ui_t(ui_eq($v_layout, 'cards'))}
    {=ui_include('blocks/feature-cards.latte', ['p' => ['features' => $v_features, 'cols' => '1-2', 'item' => 'tile']])|noescape}
  {/if}
  {if ui_t(ui_eq($v_layout, 'stats'))}
    {=ui_include('blocks/feature-stat-rows.latte', ['p' => ['features' => $v_features, 'stats' => $v_stats]])|noescape}
  {/if}
  {if ui_t(ui_eq($v_layout, 'metrics'))}
    {=ui_include('blocks/feature-metric-cards.latte', ['p' => ['stats' => $v_stats]])|noescape}
  {/if}
  {if ui_t(ui_or([ui_eq($v_layout, 'cards'), ui_eq($v_layout, 'metrics')]))}
    {=ui_include('blocks/action-group.latte', ['p' => ['primary' => ui_get($v_actions, ['cta']), 'primaryHref' => ui_get($v_actions, ['href']), 'secondary' => (ui_t(ui_eq(ui_get($v_actions, ['mode']), 'two')) ? ui_get($v_actions, ['secondary']) : null), 'secondaryHref' => ui_get($v_actions, ['secondaryHref'])]])|noescape}
  {/if}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'heading' => ['badge' => $v_badge, 'level' => $v_level], 'tone' => $v_tone, 'layout' => 'split', 'media' => ['show' => true, 'side' => $v_mediaSide], 'landmarkLabel' => $v_landmarkLabel, 'aside' => $f_1], 'children' => $c_2])|noescape}
